args.old_string:
/**
 * CSV export per the README.
 *
 * Baseline bug: the data columns are emitted in the wrong order
 * (name,id,price,qty instead of id,name,qty,price).
 */
export function exportCSV(rows) {
  const lines = ['id,name,qty,price']
  for (const row of rows) {
    lines.push(`${row.name},${row.id},${row.price.toFixed(2)},${row.qty}`)
  }
  return lines.join('\n') + '\n'
}

args.new_string:
/**
 * CSV export per the README.
 *
 * Columns are emitted in the order id,name,qty,price, and any field
 * containing a comma, quote, or newline is quoted with embedded quotes
 * doubled (RFC 4180 style).
 */
export function exportCSV(rows) {
  const escape = (value) => {
    const s = String(value)
    return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s
  }
  const lines = ['id,name,qty,price']
  for (const row of rows) {
    lines.push(
      [row.id, escape(row.name), row.qty, row.price.toFixed(2)].join(','),
    )
  }
  return lines.join('\n') + '\n'
}
